package org.botai.back.b2b;

import java.util.*;
import org.botai.back.catalog.TaskSnapshot;
import org.botai.back.common.*;
import org.botai.back.expert.ExpertReviewDocument;
import org.botai.back.grading.port.GradingGateway;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.*;
import tools.jackson.databind.node.*;
import tools.jackson.databind.json.JsonMapper;
import static org.assertj.core.api.Assertions.*;

class B2bAiResponseValidatorTest {
 static final JsonCodec JSON=new JsonCodec(JsonMapper.builder().build());
 final B2bAiResponseValidator validator=new B2bAiResponseValidator(JSON,new ExpertReviewDocument(JSON));
 static final TaskSnapshot TASK=new TaskSnapshot(UUID.randomUUID(),UUID.randomUUID(),16,2,"Условие","Ответ",null,List.of(),false);
 static final List<GradingGateway.Image> IMAGES=List.of(new GradingGateway.Image(UUID.randomUUID(),new byte[]{1},"image/jpeg"));
 static ObjectNode body(){var root=(ObjectNode)JSON.read("{\"task\":{},\"solution_image_ids\":[],\"is_graded\":true,\"rejection_reason\":\"\",\"ocr\":{\"steps\":[{\"id\":\"s1\",\"type\":\"transform\",\"title\":\"Первое\",\"lines\":[\"x=2\",\"y=3\"],\"figure\":null},{\"id\":\"s2\",\"type\":\"answer\",\"title\":\"Ответ\",\"lines\":[\"x=2\"],\"figure\":null}],\"answer\":\"2\"},\"analysis\":{\"summary\":\"Ошибка\",\"checks\":{\"domain\":null,\"transformations\":null,\"completeness\":{\"is_complete\":true,\"reason\":\"Все шаги\"}},\"student_answer\":null,\"errors\":[],\"strengths\":[],\"statuses\":[{\"id\":\"s1\",\"status\":\"error\",\"note\":\"Ошибка\",\"correct\":\"x=1\",\"follows_from_step_ids\":[]},{\"id\":\"s2\",\"status\":\"consequence\",\"note\":\"Из ошибки\",\"correct\":\"1\",\"follows_from_step_ids\":[\"s1\"]}]},\"grading\":{\"score\":1,\"criterion\":\"Критерий\",\"explanation\":\"Ошибка\"},\"artifacts\":[]}");root.set("task",JSON.read(JSON.write(org.botai.back.grading.AiResponseValidator.task(TASK))));root.set("solution_image_ids",JSON.read(JSON.write(IMAGES.stream().map(i->i.id().toString()).toList())));return root;}
 B2bAiResponseValidator.Parsed parse(ObjectNode root){return validator.parse(new GradingGateway.Response(JSON.write(root),"mock","pin",null),TASK,IMAGES,"pin","mock",false);}
 @Test void oneStepRetainsTitleLinesAndExplicitCausalLink(){var parsed=parse(body());var result=validator.adapt(parsed,d->{throw new AssertionError();});JsonNode doc=JSON.read(JSON.write(result.feedback()));assertThat(doc.path("schema_version").asText()).isEqualTo("expert-review.v2");assertThat(doc.path("ocr").path("blocks")).hasSize(2);assertThat(doc.path("ocr").path("blocks").get(0).path("title").asText()).isEqualTo("Первое");assertThat(doc.path("ocr").path("blocks").get(0).path("content").path("lines")).hasSize(2);assertThat(doc.path("analysis").path("block_reviews").get(1).path("follows_from_block_ids").get(0).asText()).isEqualTo("s1");assertThat(result.demo()).isTrue();}
 @Test void duplicateUnknownFieldsLegacyOcrAndUnboundEchoAreRejected(){var base=body();for(String invalid:List.of(JSON.write(base).replaceFirst("\\{","{\"task\":{},"),JSON.write(base)+"{}"," "+JSON.write(base))){assertThatThrownBy(()->validator.parse(new GradingGateway.Response(invalid,"mock","pin",null),TASK,IMAGES,"pin","mock",false)).extracting("code").isEqualTo("invalid_ai_response");}var unknown=body();unknown.put("reasoning_content","secret");assertThatThrownBy(()->parse(unknown)).isInstanceOf(ApiException.class);var legacy=body();legacy.put("ocr","raw");assertThatThrownBy(()->parse(legacy)).isInstanceOf(ApiException.class);var foreign=body();((ObjectNode)foreign.path("task")).put("id",UUID.randomUUID().toString());assertThatThrownBy(()->parse(foreign)).isInstanceOf(ApiException.class);}
 @Test void causalRefsCannotBeOmittedDuplicatedInferredOrPointForward(){for(int variant=0;variant<5;variant++){var root=body();var statuses=(ArrayNode)root.path("analysis").path("statuses");var second=(ObjectNode)statuses.get(1);switch(variant){case 0->second.remove("follows_from_step_ids");case 1->second.set("follows_from_step_ids",JSON.read("[]"));case 2->second.set("follows_from_step_ids",JSON.read("[\"s1\",\"s1\"]"));case 3->second.set("follows_from_step_ids",JSON.read("[\"s2\"]"));case 4->((ObjectNode)statuses.get(0)).put("status","minor");}assertThatThrownBy(()->parse(root)).isInstanceOf(ApiException.class);}}
 @Test void diagramIsServerRemappedOnlyAfterFullValidation(){var root=body();UUID ai=UUID.randomUUID(),backend=UUID.randomUUID();((ArrayNode)root.get("artifacts")).add(JSON.read(JSON.write(Map.of("id",ai,"kind","diagram","source_image_id",IMAGES.getFirst().id(),"bbox",Map.of("x",0.1,"y",0.1,"width",0.5,"height",0.5),"media_type","image/jpeg","byte_size",100,"width",32,"height",32,"sha256","a".repeat(64)))));var step=(ObjectNode)root.path("ocr").path("steps").get(0);step.set("lines",JSON.read("[]"));step.set("figure",JSON.read(JSON.write(Map.of("kind","image","artifact_id",ai,"alt","Чертёж"))));var parsed=parse(root);var result=validator.adapt(parsed,d->{assertThat(d.source()).isEqualTo(IMAGES.getFirst().id());return backend;});assertThat(JSON.write(result.feedback())).contains(backend.toString()).doesNotContain(ai.toString());((ObjectNode)root.path("artifacts").get(0)).put("source_image_id",UUID.randomUUID().toString());assertThatThrownBy(()->parse(root)).isInstanceOf(ApiException.class);}
 @Test void foreignFiguresArtifactUnknownFieldsAndInvalidBoxesFail(){UUID aid=UUID.randomUUID();var r=body();((ObjectNode)r.path("ocr").path("steps").get(0)).set("figure",JSON.read(JSON.write(Map.of("kind","image","artifact_id",aid,"alt","image"))));assertThatThrownBy(()->parse(r)).isInstanceOf(ApiException.class);var pure=body();((ObjectNode)pure.path("ocr").path("steps").get(0)).set("lines",JSON.read("[]"));assertThatThrownBy(()->parse(pure)).isInstanceOf(ApiException.class);}
 @Test void manualSnapshotCanBeExtractedButIdsNumberAndMaxRemainBound(){var root=body();((ObjectNode)root.get("task")).put("statement","Новое условие");assertThatThrownBy(()->parse(root)).isInstanceOf(ApiException.class);var parsed=validator.parse(new GradingGateway.Response(JSON.write(root),"mock","pin",null),TASK,IMAGES,"pin","mock",true);assertThat(parsed.task().statement()).isEqualTo("Новое условие");((ObjectNode)root.get("task")).put("task_number",18);assertThatThrownBy(()->validator.parse(new GradingGateway.Response(JSON.write(root),"mock","pin",null),TASK,IMAGES,"pin","mock",true)).isInstanceOf(ApiException.class);}
 @Test void obsoleteProposedNumericNumberLineWireIsRejectedWithoutInventingPrArcs(){var root=body();var figure=JSON.read("{\"kind\":\"number_line\",\"axis_label\":\"x\",\"points\":[{\"id\":\"p1\",\"value\":-1.5,\"label_latex\":\"-3/2\",\"marker\":\"open\",\"sign\":\"0\"}],\"intervals\":[{\"left_point_id\":null,\"right_point_id\":\"p1\",\"sign\":\"-\",\"selected\":false},{\"left_point_id\":\"p1\",\"right_point_id\":null,\"sign\":\"+\",\"selected\":true}]}");((ObjectNode)root.path("ocr").path("steps").get(0)).set("figure",figure);assertThatThrownBy(()->parse(root)).isInstanceOf(ApiException.class);}
 @Test void obsoleteProposedNumericCircleWireIsRejectedWithoutInventingPrPoints(){var root=body();var figure=JSON.read("{\"kind\":\"unit_circle\",\"points\":[{\"id\":\"p1\",\"angle_rad\":5.235987755982989,\"label_latex\":\"-π/3\",\"marker\":\"closed\"}],\"arcs\":[{\"from_point_id\":\"p1\",\"to_point_id\":\"p1\",\"direction\":\"cw\",\"full_circle\":true,\"selected\":false}]}");((ObjectNode)root.path("ocr").path("steps").get(0)).set("figure",figure);assertThatThrownBy(()->parse(root)).isInstanceOf(ApiException.class);}
 @Test void explicitPenaltiesAndCorrectionMeaningSurviveWithoutScoreRecalculation(){var root=body();((ObjectNode)root.get("grading")).put("score",0);var errors=(ArrayNode)root.path("analysis").path("errors");for(int n=0;n<2;n++){Map<String,Object> e=new LinkedHashMap<>();e.put("id","e"+n);e.put("code",null);e.put("description","Ошибка");e.put("where","Строка");e.put("correct_version","x=1");e.put("advice","Проверь");e.put("step_id",n==0?"s1":"s2");e.put("penalty",n==0?2:0);errors.add(JSON.read(JSON.write(e)));}var result=validator.adapt(parse(root),d->{throw new AssertionError();});var doc=JSON.read(JSON.write(result.feedback()));assertThat(doc.path("analysis").path("findings").get(0).path("penalty").asInt()).isEqualTo(2);assertThat(doc.path("analysis").path("findings").get(1).path("penalty").isIntegralNumber()).isTrue();assertThat(doc.path("analysis").path("findings").get(1).path("penalty").asInt()).isZero();assertThat(doc.path("analysis").path("block_reviews").get(0).path("explanation").asText()).contains("x=1");assertThat(result.score()).isZero();}
 @Test void semanticHashBindsNumberExactInputAndOrderedSolutionBytes(){byte[] a={1},b={2};String h=LocalDemoService.inputHash(16,a,List.of(a,b));assertThat(h).isEqualTo(LocalDemoService.inputHash(16,a,List.of(a,b))).isNotEqualTo(LocalDemoService.inputHash(14,a,List.of(a,b))).isNotEqualTo(LocalDemoService.inputHash(16,b,List.of(a,b))).isNotEqualTo(LocalDemoService.inputHash(16,a,List.of(b,a)));}
 @Test void observerWhitelistsFactsAndNeverForwardsSecretsUrlsOrRawArtifacts(){var safe=LocalDemoEvents.safeData(JSON.read("{\"attempt\":2,\"duration_ms\":12.5,\"error_code\":\"format_invalid\",\"prompt\":\"secret\",\"reasoning_content\":\"secret\",\"headers\":{},\"artifact_id\":\""+UUID.randomUUID()+"\",\"url\":\"https://example.test\"}"));assertThat(safe).containsEntry("attempt",2).containsEntry("durationMs",12.5).containsEntry("errorCode","format_invalid");assertThat(safe).doesNotContainKeys("prompt","reasoning_content","headers","url","artifact_id");assertThat(LocalDemoEvents.safeData(JSON.read("{\"error_code\":\"my_lowercase_secret\"}"))).isEmpty();}
 @Test void observerCompletionCauseCodesDoNotBroadenMetadataWhitelist(){
  for(String code:List.of("llm_bad_response","provider_empty_choices","provider_output_truncated")){
   var safe=LocalDemoEvents.safeData(JSON.read(JSON.write(Map.of("code",code,"error_code",code,"finish_reason","length","empty_choices",true,"prompt_tokens",42,"completion_tokens",8000,"reasoning_tokens",7999,"issue_paths",List.of("$.analysis"),"issue_codes",List.of("invalid_stage_response"),"raw_response","PRIVATE MODEL TEXT"))));
   assertThat(safe).containsOnly(entry("code",code),entry("errorCode",code),entry("issueCodes",List.of("invalid_stage_response")),entry("issuePaths",List.of("$.analysis")));
  }
  assertThat(LocalDemoEvents.safeData(JSON.read("{\"code\":\"private_lowercase_secret\",\"error_code\":\"provider_unknown_private\",\"reasoning_content\":\"PRIVATE REASONING\",\"provider_response\":\"PRIVATE RESPONSE\"}"))).isEmpty();
 }
}
